challenge.solution:
#include <iostream>
#include <vector>

int main() {
    const std::vector<int> values{1, 2, 3, 4}; int total = 0;
    for (const auto value : values) { if (value % 2 == 0) total += value * value; }
    std::cout << "even squares: " << total << '\n';
}

