challenge.solution:
#include <iostream>
class Counter { public: void add(int amount) { value_ += amount; } void reset() { value_ = 0; } int value() const { return value_; } private: int value_ = 0; };
int main() { Counter counter; counter.add(3); counter.reset(); std::cout << counter.value() << '\n'; }
